update workflow_definition
code = #{code}, name = #{name}, scene = #{scene}, scope_type = #{scopeType}, scope_id = #{scopeId}, default_flow = #{defaultFlow}, active_for_new = #{activeForNew}, enabled = #{enabled}, description = #{description}, version = #{version}, lifecycle = #{lifecycle}, published_time = #{publishedTime}, published_by = #{publishedBy}, source_flow_id = #{sourceFlowId}, update_time = #{updateTime}
