mapper.select:
select id, code, name, scene, scope_type, scope_id, default_flow, active_for_new, enabled, description, version, lifecycle,
       published_time, published_by, source_flow_id, create_time, update_time
from workflow_definition
where scene = #{scene}

    and scope_type = #{scopeType}


    and scope_id = #{scopeId}

order by active_for_new desc, code asc, version desc, create_time asc

mapper.update:
update workflow_role
code = #{code}, name = #{name}, role_type = #{roleType}, role_id = #{roleId}, field_key = #{fieldKey}, source_type = #{sourceType}, source_key = #{sourceKey}, match_mode = #{matchMode}, enabled = #{enabled}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select id, flow_id, code, name, role_type, role_id, field_key, source_type, source_key, match_mode, enabled, create_time, update_time
from workflow_role
where id = #{id}

select id, flow_id, status_flow_id, workflow_role_id, visible, operable, enabled, create_time, update_time
from status_flow_role_permission
where flow_id = #{flowId}

select p.id, p.flow_id, p.status_flow_id, p.workflow_role_id, p.visible, p.operable, p.enabled, p.create_time, p.update_time
from status_flow_role_permission p
  inner join workflow_definition wd on wd.id = p.flow_id
  inner join status_flow sf on sf.id = p.status_flow_id
where wd.scene = #{scene}
  and wd.scope_type = #{scopeType}
  and wd.scope_id = #{scopeId}
  and wd.enabled = b'1'
  and p.enabled = b'1'
  and p.operable = b'1'
  and sf.from_id = #{fromStatusId}
  and sf.to_id = #{toStatusId}
